#!/usr/bin/env bash
set -Eeuo pipefail

ROOT="$(git rev-parse --show-toplevel 2>/dev/null || true)"
[[ -n "$ROOT" ]] || { echo "ERROR: run inside MEMEFLOW repo"; exit 1; }
cd "$ROOT"

BRANCH="chart-debug-20260829-161234"
EXPECTED_HEAD="7e1268f7a29f097d2493febe4318ed40d6e9dad6"

APP="memeflow-app/app-server.mjs"
PKG="memeflow-app/package.json"
HTML="memeflow-app/owner-intelligence.html"
JS="memeflow-app/owner-intelligence.js"
CSS="memeflow-app/owner-intelligence.css"
MODULE="memeflow-app/src/v24-probation-evidence-gate-v24_2.mjs"
TEST="memeflow-app/tests/v24-probation-evidence-gate-v24_2.mjs"

MODIFIED=("$APP" "$PKG" "$HTML" "$JS" "$CSS")
NEW_FILES=("$MODULE" "$TEST")
ALL_FILES=("${MODIFIED[@]}" "${NEW_FILES[@]}")

echo "=== MEMEFLOW V24.2 PROBATION EVIDENCE GATE ==="

[[ "$(git branch --show-current)" == "$BRANCH" ]] || {
  echo "V24.2 REFUSED: wrong branch"; exit 1;
}

[[ "$(git rev-parse HEAD)" == "$EXPECTED_HEAD" ]] || {
  echo "V24.2 REFUSED: audited HEAD changed"
  echo "expected: $EXPECTED_HEAD"
  echo "actual: $(git rev-parse HEAD)"
  exit 1
}

for f in "${MODIFIED[@]}"; do
  [[ -f "$f" ]] || { echo "V24.2 REFUSED: missing $f"; exit 1; }
  git diff --quiet -- "$f" || { echo "V24.2 REFUSED: tracked local changes in $f"; exit 1; }
  git diff --cached --quiet -- "$f" || { echo "V24.2 REFUSED: staged local changes in $f"; exit 1; }
done

for f in "${NEW_FILES[@]}"; do
  [[ ! -e "$f" ]] || { echo "V24.2 REFUSED: target already exists: $f"; exit 1; }
done

echo "V24.2 PRECHECK_OK"
echo "Untracked installer/runtime files are allowed and remain untouched."

STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP=".memeflow-backups/v24-2-probation-evidence-gate-$STAMP"
mkdir -p "$BACKUP"

for f in "${MODIFIED[@]}"; do
  mkdir -p "$BACKUP/$(dirname "$f")"
  cp "$f" "$BACKUP/$f"
done

rollback(){
  rc=$?
  if [[ $rc -ne 0 ]]; then
    echo
    echo "=== V24.2 FAILED - RESTORING ==="
    for f in "${MODIFIED[@]}"; do
      [[ -f "$BACKUP/$f" ]] && cp "$BACKUP/$f" "$f" || true
    done
    for f in "${NEW_FILES[@]}"; do rm -f "$f"; done
    git reset -- "${ALL_FILES[@]}" >/dev/null 2>&1 || true
    echo "ROLLBACK_COMPLETE; backup: $BACKUP"
  fi
  exit "$rc"
}
trap rollback EXIT INT TERM

echo '' | base64 -d > "$MODULE"
echo '' | base64 -d > "$TEST"
echo '' | base64 -d > /tmp/mf-v24-2-transform.py
echo '' | base64 -d > /tmp/mf-v24-2-audit.py

python3 /tmp/mf-v24-2-transform.py

python3 - <<'PY'
from pathlib import Path
for name in [
 "memeflow-app/app-server.mjs",
 "memeflow-app/package.json",
 "memeflow-app/owner-intelligence.html",
 "memeflow-app/owner-intelligence.js",
 "memeflow-app/owner-intelligence.css",
 "memeflow-app/src/v24-probation-evidence-gate-v24_2.mjs",
 "memeflow-app/tests/v24-probation-evidence-gate-v24_2.mjs"
]:
    p=Path(name)
    p.write_text(p.read_text(encoding="utf-8").rstrip("\n")+"\n",encoding="utf-8")
print("V24_2_EOF_NORMALIZATION_OK")
PY

echo
echo "=== V24.2 SYNTAX ==="
node --check "$APP"
node --check "$MODULE"
node --check "$TEST"
node --check "$JS"
node -e "JSON.parse(require('fs').readFileSync('$PKG','utf8')); console.log('PACKAGE_JSON_OK')"
echo "SYNTAX_OK"

echo
echo "=== V24.2 TARGETED TESTS ==="
(
  cd memeflow-app
  node tests/controlled-policy-bridge-v24_0.mjs
  node tests/v24-probation-telemetry-v24_1.mjs
  node tests/v24-probation-evidence-gate-v24_2.mjs
  node tests/shadow-e2e-readiness-freeze-v23_23.mjs
  node tests/assist-fresh-decision-v22.mjs
)
echo "TARGETED_TESTS_OK"

echo
echo "=== V24.2 FULL TEST SUITE ==="
(
  cd memeflow-app
  npm test
)
echo "FULL_TEST_SUITE_OK"

echo
echo "=== V24.2 CONTRACT AUDIT ==="
python3 /tmp/mf-v24-2-audit.py

git diff --check -- "${ALL_FILES[@]}"

echo
echo "=== V24.2 DIFF ==="
git diff --stat -- "${ALL_FILES[@]}"

git reset >/dev/null
git add "${ALL_FILES[@]}"

ALLOWED_RE='^memeflow-app/(app-server\.mjs|package\.json|owner-intelligence\.html|owner-intelligence\.js|owner-intelligence\.css|src/v24-probation-evidence-gate-v24_2\.mjs|tests/v24-probation-evidence-gate-v24_2\.mjs)$'

BAD="$(
  git diff --cached --name-only |
  grep -Ev "$ALLOWED_RE" ||
  true
)"

if [[ -n "$BAD" ]]; then
  echo "V24.2 REFUSED: unrelated staged files:"
  echo "$BAD"
  git reset
  exit 1
fi

git diff --cached --check
echo
echo "=== V24.2 STAGED ==="
git diff --cached --stat

git commit -m "feat: add v24.2 probation evidence gate"
git push origin HEAD

trap - EXIT INT TERM

echo
echo "=== DONE ==="
echo "Backup: $BACKUP"
git log -1 --oneline --decorate

echo
echo "V24.2 CONTRACT:"
echo "  consumes V24.1 telemetry + V23 readiness + V24.0 bridge status"
echo "  >=100 directional / >=40 negative / >=20 positive"
echo "  >=50 SHADOW interventions"
echo "  resolution rate >=75%"
echo "  blocked-negative precision >=65%"
echo "  Wilson 95% lower precision bound >=55%"
echo "  positive opportunity cost <=35%"
echo "  PASS means MANUAL ENFORCE REVIEW only"
echo "  no automatic mode change"
echo "  no apply/tune endpoint"
echo "  no Score/State/Settings/BUY/SELL/forecast mutation"
